import{_ as h,C as d,o as a,c,a2 as s,b as o,w as t,a as r,E as n,a3 as l}from"./chunks/framework.Ci_RTJJ5.js";const y=JSON.parse('{"title":"07 — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/07-context-budget/overview.md","filePath":"chapters/07-context-budget/overview.md"}'),p={name:"chapters/07-context-budget/overview.md"};function u(g,e,m,b,v,w){const i=d("Mermaid");return a(),c("div",null,[e[2]||(e[2]=s(`<h1 id="_07-—-overview" tabindex="-1">07 — Overview <a class="header-anchor" href="#_07-—-overview" aria-label="Permalink to &quot;07 — Overview&quot;">​</a></h1><p><em>How a context budget works, and what pruning must not break. Read this before you write code.</em></p><hr><h2 id="two-budgets-and-the-bigger-one-is-invisible" tabindex="-1">Two budgets, and the bigger one is invisible <a class="header-anchor" href="#two-budgets-and-the-bigger-one-is-invisible" aria-label="Permalink to &quot;Two budgets, and the bigger one is invisible&quot;">​</a></h2><p>A request costs tokens in two places:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  system message     ~50 tokens</span></span>
<span class="line"><span>  conversation       grows every turn</span></span>
<span class="line"><span>  tool schemas       ~200 tokens per request, forever</span></span></code></pre></div><p>The third line surprises people. Tool schemas are sent with <strong>every</strong> request, whether or not the model calls a tool. They are a fixed tax on every turn.</p><p>Measured on a real harness (fx, 13 tools): a cold request was 23,884 bytes, of which 15,560 were tool schemas. Sixty-five percent of the request was definitions. The conversation had not started yet.</p>`,8)),(a(),o(l,null,{default:t(()=>[n(i,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20R%5B%22request%22%5D%20--%3E%20S%5B%22system%3Cbr%2F%3Efixed%22%5D%0A%20%20%20%20R%20--%3E%20C%5B%22conversation%3Cbr%2F%3Egrows%22%5D%0A%20%20%20%20R%20--%3E%20T%5B%22tool%20schemas%3Cbr%2F%3Efixed%20per%20request%22%5D%0A%20%20%20%20S%20--%3E%20E%5B%22estimate%22%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20T%20--%3E%20E%0A%20%20%20%20E%20--%3E%20D%7Bbudget%3F%7D%0A%20%20%20%20D%20--%20%22under%22%20--%3E%20SEND%5B%22send%20as%20is%22%5D%0A%20%20%20%20D%20--%20%22over%22%20--%3E%20P%5B%22prune%20conversation%20only%22%5D%0A%20%20%20%20P%20--%3E%20M%5B%22marked%20stub%22%5D%0A%20%20%20%20M%20--%3E%20SEND%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s(`<p>Consequences:</p><ul><li>pruning the conversation cannot rescue a request whose schemas alone exceed the budget;</li><li>shrinking schemas (fewer tools, shorter descriptions) is a real lever, and it is why harnesses advertise tools lazily;</li><li>the estimate must count both, or the accounting lies.</li></ul><h2 id="ceiling-versus-threshold" tabindex="-1">Ceiling versus threshold <a class="header-anchor" href="#ceiling-versus-threshold" aria-label="Permalink to &quot;Ceiling versus threshold&quot;">​</a></h2><p>A <strong>threshold</strong> triggers work when a number is crossed. A <strong>ceiling</strong> is a constraint every request must satisfy.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  threshold:  if tokens &gt; 8000 then prune      ← may fire a turn too late</span></span>
<span class="line"><span>  ceiling:    fit(messages, 8000) on every request</span></span></code></pre></div><p>Thresholds are easier and they overshoot. A single large tool result can push a request past the window before any threshold notices, and the request fails with a provider error rather than being adjusted.</p><p>So the rule here is the stricter one: every outgoing request is fitted. The cost is fitting on every turn, which is a few hundred microseconds of arithmetic.</p><h2 id="pruning-is-a-decorator" tabindex="-1">Pruning is a decorator <a class="header-anchor" href="#pruning-is-a-decorator" aria-label="Permalink to &quot;Pruning is a decorator&quot;">​</a></h2><p>The budget has to apply to every request the loop makes, including the ones in later turns. There are two ways to get that:</p><ol><li>put a <code>Trim</code> call inside the loop;</li><li>wrap the provider.</li></ol><p>This chapter wraps:</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">provider </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agent.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WithBudget</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(provider, maxContext, emit)</span></span></code></pre></div>`,12)),(a(),o(l,null,{default:t(()=>[n(i,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20L%5B%22loop%22%5D%20--%3E%7C%22Stream(req)%22%7C%20B%5B%22budget%20decorator%22%5D%0A%20%20%20%20B%20--%3E%7C%22fit(req.Messages)%22%7C%20B%0A%20%20%20%20B%20--%3E%7C%22Stream(fitted)%22%7C%20P%5B%22real%20provider%22%5D%0A%20%20%20%20P%20--%3E%20W%5B%22wire%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=s(`<p>The loop still sends a conversation and still knows nothing about tokens. The decorator is where policy lives, which is exactly what the seam from chapter 01 was for. Chapter 08 uses the same trick for cancellation.</p><h2 id="what-survives-a-cut" tabindex="-1">What survives a cut <a class="header-anchor" href="#what-survives-a-cut" aria-label="Permalink to &quot;What survives a cut&quot;">​</a></h2><p>Four rules, in priority order:</p><table tabindex="0"><thead><tr><th>Priority</th><th>Rule</th><th>Why</th></tr></thead><tbody><tr><td>1</td><td>keep the system message</td><td>instructions are not negotiable</td></tr><tr><td>2</td><td>keep the newest messages</td><td>the current task is what the model needs</td></tr><tr><td>3</td><td>never keep a tool result without its call</td><td>the conversation becomes invalid</td></tr><tr><td>4</td><td>leave a marker where history was removed</td><td>the model must know it is blind there</td></tr></tbody></table><p>Rule 3 is the one that is easy to miss and expensive to debug. Walking backwards means the cut lands wherever the budget runs out, which can be between an assistant message and its tool results:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  ... assistant: call_1   ← dropped</span></span>
<span class="line"><span>      tool: call_1 result ← kept          invalid</span></span></code></pre></div><p>Dropping the orphaned result is the cheapest fix and it is what this chapter grades.</p><h2 id="the-marker-matters-more-than-it-looks" tabindex="-1">The marker matters more than it looks <a class="header-anchor" href="#the-marker-matters-more-than-it-looks" aria-label="Permalink to &quot;The marker matters more than it looks&quot;">​</a></h2><p>Without it, the model sees a conversation that begins mid-sentence and concludes that this is the whole history. It will answer confidently about work it cannot see.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[context pruned: 31 earlier messages omitted to fit 2000 tokens]</span></span></code></pre></div><p>That line costs almost nothing and changes the answer from confident to cautious.</p><h2 id="estimation-is-allowed-to-be-crude" tabindex="-1">Estimation is allowed to be crude <a class="header-anchor" href="#estimation-is-allowed-to-be-crude" aria-label="Permalink to &quot;Estimation is allowed to be crude&quot;">​</a></h2><p>An exact tokenizer needs a vocabulary, a model-specific table, and a dependency. The decision being made, &quot;is this over budget&quot;, has a wide margin, so four bytes per token is enough.</p><p>Two properties matter more than accuracy:</p><ol><li><strong>monotonic.</strong> Adding content never lowers the estimate. Otherwise pruning oscillates: drop, re-estimate lower, stop dropping, overflow.</li><li><strong>counts everything that is sent.</strong> Messages, tool calls inside messages, and tool schemas.</li></ol><p>Divide by four <strong>once at the end</strong>. Dividing per message rounds every small cost to zero and under-counts long conversations by a lot.</p><h2 id="what-this-chapter-deliberately-does-not-do" tabindex="-1">What this chapter deliberately does not do <a class="header-anchor" href="#what-this-chapter-deliberately-does-not-do" aria-label="Permalink to &quot;What this chapter deliberately does not do&quot;">​</a></h2><ul><li><strong>No summarisation.</strong> Dropped messages are gone from the request, not replaced by a summary. The session file keeps them, which is what makes a later chapter able to add summarisation without losing data.</li><li><strong>No recall tool.</strong> A model cannot ask for a pruned message back. pi-condense does exactly that with a <code>context_tree_query</code> tool, and it is the natural next step after this chapter.</li><li><strong>No schema pruning.</strong> The tool definitions are counted but never reduced. Fewer tools, lazy schemas, and description caps are a separate mechanism.</li></ul><h2 id="where-the-real-implementations-go-further" tabindex="-1">Where the real implementations go further <a class="header-anchor" href="#where-the-real-implementations-go-further" aria-label="Permalink to &quot;Where the real implementations go further&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Implementation</th></tr></thead><tbody><tr><td>Recovery of pruned content</td><td>pi-condense, <code>context_tree_query</code></td></tr><tr><td>Tool-schema gating</td><td>toolflow, stage-gated mounting</td></tr><tr><td>Compaction as a session entry</td><td>pi, <code>compaction</code> record type</td></tr><tr><td>The bug this chapter prevents</td><td>pi-context-prune, which deletes results and orphans calls</td></tr></tbody></table><p>The last row is worth reading. A published, widely used pruning extension shipped the exact failure that rule 3 describes: it removed tool results, kept the calls, and let the provider synthesise an error result in their place.</p><h2 id="self-check" tabindex="-1">Self-check <a class="header-anchor" href="#self-check" aria-label="Permalink to &quot;Self-check&quot;">​</a></h2><ol><li>Which part of a request is a fixed cost per turn, and roughly how large is it? <em>(Two budgets, and the bigger one is invisible)</em></li><li>Why is a ceiling stricter than a threshold, and what does the extra strictness cost? <em>(Ceiling versus threshold)</em></li><li>Why is the budget a decorator rather than a line in the loop? <em>(Pruning is a decorator)</em></li><li>Which rule prevents an invalid conversation, and what does the cut look like when it is violated? <em>(What survives a cut)</em></li><li>Name the two properties an estimate needs more than accuracy. <em>(Estimation is allowed to be crude)</em></li></ol>`,23))])}const f=h(p,[["render",u]]);export{y as __pageData,f as default};
